 box.querySelectorAll('[data-prway]').forEach(b=>b.onchange=()=>{const r=purchaseDraft.rows.find(x=>x.id===b.dataset.prway),p=getPurchaseP(r),way=purchaseWay(p,b.value);r.way=b.value;r.costC=Number.isInteger(way?.priceC)?way.priceC:null;setTimeout(renderPurchaseRows,0);savePurchaseDraft()});
