async function addPurchaseUnit(id){const row=purchaseDraft.rows.find(x=>x.id===id),p=getPurchaseP(row);if(!p)return;const label=prompt(`اسم الوحدة الجديدة لصنف «${p.name}» — مثال: كيس / زجاجة / شرينك`);if(!label?.trim())return;const v=prompt(`كل ${label.trim()} يساوي كام ${isWeight(p)?'جرام':'وحدة بيع'}؟\nمثال: كيس 6 قطع = 6، أو شوال 25 كيلو = 25000 جرام`);if(v===null)return;const base=num(v);if(!Number.isFinite(base)||base<=0||(!isWeight(p)&&!Number.isInteger(base)))return toast('معامل تحويل غير صحيح');if((p.packages||[]).some(x=>norm(x.label)===norm(label)))return toast('الوحدة موجودة بالفعل لهذا الصنف');if(!confirm(`إضافة «${label.trim()}» = ${fmt(base)} ${isWeight(p)?'جرام':'وحدة'} للصنف «${p.name}»؟`))return;const fresh=await one('products',p.id);const pack={id:uid('PK'),label:label.trim(),qtyBase:base,priceC:null};fresh.packages=[...(fresh.packages||[]),pack];const at=now(),tx=db.transaction(['products','audit'],'readwrite');tx.objectStore('products').put(fresh);tx.objectStore('audit').add({id:uid('AU'),action:'add_purchase_unit',reference:fresh.id,unit:pack.label,qtyBase:base,createdAt:at,actor:'cashier'});await done(tx);purchaseCatalog=purchaseCatalog.map(x=>x.id===p.id?fresh:x);row.way='pkg:'+pack.id;row.costC=null;savePurchaseDraft();renderPurchaseRows();toast('تمت إضافة الوحدة للصنف')}
function purchaseAddProduct(p){let r=purchaseDraft.rows.find(r=>r.productId===p.id);if(r){r.quantity=(Number(r.quantity)||0)+1;toast('الصنف موجود: زودت كميته في نفس الصف')}else{r=makePurchaseRow(p);purchaseDraft.rows.push(r);toast('اتضاف الصنف لجدول الوارد')}savePurchaseDraft();renderPurchaseRows();return r}
function purchaseBarcode(code){const val=String(code||'').trim(),p=purchaseCatalog.find(x=>x.barcode===val||x.code===val);if(!p)return toast('الباركود غير موجود ضمن الأصناف');purchaseAddProduct(p)}
function stopPurchaseScanner(){if(purchaseScannerTimer){clearInterval(purchaseScannerTimer);purchaseScannerTimer=null}if(purchaseStream){purchaseStream.getTracks().forEach(x=>x.stop());purchaseStream=null}const v=$('#purchaseVideo');if(v)v.srcObject=null}
const originalCloseModal=closeModal;
