async function supplierBalances(){const es=await all('payables'),group=new Map();for(const e of es){const name=e.supplier||'مورد غير محدد',entry=group.get(name)||{supplier:name,amountC:0,events:0};entry.amountC+=e.amountC;entry.events++;group.set(name,entry)}return [...group.values()].filter(x=>x.amountC>0).sort((a,b)=>b.amountC-a.amountC)}
async function showSupplierPayment(){if(!await requireOpenDay())return;const list=await supplierBalances();if(!list.length)return toast('لا توجد مديونيات موردين مستحقة');modal('سداد مورد',`<label class="form-label">المورد</label><select id="supplierSelected" class="field">${options(list.map(x=>[x.supplier,x.supplier+' · '+money(x.amountC)]))}</select>${field('supplierPayment','المبلغ المدفوع بالجنيه','','number')}${field('supplierPaymentNote','ملاحظة (اختياري)','','text')}<div class="list-card" id="supplierPaymentPreview"></div><button id="confirmSupplierPayment" class="btn primary block spaced">تأكيد سداد المورد من الخزنة</button>`);const update=()=>{const chosen=list.find(x=>x.supplier===$('#supplierSelected').value),v=num($('#supplierPayment').value),amt=cents(v);$('#supplierPaymentPreview').innerHTML=`الرصيد المستحق: <b>${money(chosen?.amountC||0)}</b><div class="hint">بعد السداد: ${Number.isFinite(v)&&v>0&&amt<=chosen.amountC?money(chosen.amountC-amt):'راجع المبلغ'}</div>`};$('#supplierSelected').onchange=update;$('#supplierPayment').oninput=update;update();$('#confirmSupplierPayment').onclick=async()=>{const chosen=list.find(x=>x.supplier===$('#supplierSelected').value),v=num($('#supplierPayment').value),amt=cents(v);if(!chosen||!(v>0)||amt>chosen.amountC)return toast('المدفوع أكبر من مديونية المورد أو غير صالح');if(!confirm(`تأكيد دفع ${money(amt)} للمورد «${chosen.supplier}» من خزنة المحل؟`))return;const at=now(),dk=day(),tx=db.transaction(['payables','cash','audit'],'readwrite');tx.objectStore('payables').add({id:uid('PY'),supplier:chosen.supplier,amountC:-amt,type:'settlement',reference:$('#supplierPaymentNote').value.trim()||'سداد مديونية مورد',createdAt:at,dateKey:dk});tx.objectStore('cash').add({id:uid('CA'),amountC:-amt,type:'supplier_settlement',reference:chosen.supplier,createdAt:at,dateKey:dk});tx.objectStore('audit').add({id:uid('AU'),action:'supplier_settlement',reference:chosen.supplier,amountC:amt,createdAt:at,actor:'cashier'});await done(tx);closeModal();toast('تم السداد وتحديث مديونية المورد والكاش');renderMore()}}
