showCashMove=async function(){if(!await requireOpenDay())return;modal('حركة خزنة',`<label class="form-label">نوع الحركة</label><select id="cashType" class="field">${options([['withdraw','سحب شخصي — خارج'],['expense','مصروف محل — خارج'],['loss','فاقد / سرقة — خارج'],['deposit','إيداع نقدي — داخل'],['other_in','دخل نقدي آخر']])}</select>${field('cashAmount','المبلغ بالجنيه','','number')}${field('cashNote','سبب الحركة (مطلوب)')}<p class="hint">سداد الموردين يتم من «المزيد ← سداد مورد» حتى يتخصم من مديونية المورد مع الكاش في نفس العملية.</p><button id="saveCashMove" class="btn primary block">تأكيد الحركة</button>`);$('#saveCashMove').onclick=async()=>{const v=num($('#cashAmount').value),type=$('#cashType').value,note=$('#cashNote').value.trim();if(!(v>0)||!note)return toast('اكتب مبلغ وسبب الحركة');if(!confirm(`تأكيد ${type==='deposit'||type==='other_in'?'دخول':'خروج'} ${money(cents(v))} من الخزنة؟`))return;const sign=['deposit','other_in'].includes(type)?1:-1,at=now(),tx=db.transaction(['cash','audit'],'readwrite');tx.objectStore('cash').add({id:uid('CA'),type,amountC:cents(v)*sign,reference:note,dateKey:day(),createdAt:at});tx.objectStore('audit').add({id:uid('AU'),action:'cash_'+type,reference:note,amountC:cents(v)*sign,createdAt:at,actor:'admin'});await done(tx);closeModal();toast('تم تسجيل حركة الخزنة');renderMore()}};

function samePeriod(dk,filter){const today=day();if(filter==='all')return true;if(filter==='today')return dk===today;if(filter==='month')return dk.slice(0,7)===today.slice(0,7);if(filter==='week'){const start=new Date(today+'T12:00:00');start.setDate(start.getDate()-6);return dk>=day(start)&&dk<=today}return dk===today}
async function salesStats(filter){const [invoices,items,returns]=await Promise.all(['invoices','items','returns'].map(all));const selectedInv=invoices.filter(i=>samePeriod(i.dateKey,filter)),selectedIt=items.filter(i=>samePeriod(i.dateKey,filter)),selectedRet=returns.filter(r=>samePeriod(r.dateKey,filter)),itemMap=new Map(items.map(i=>[i.id,i]));const invoiced=selectedInv.reduce((s,i)=>s+i.totalC,0),refunded=selectedRet.reduce((s,r)=>s+r.amountC,0);
 let soldCost=0,returnCost=0,unknown=0;for(const it of selectedIt){if(it.costMissing||!Number.isFinite(it.costTotalC)){unknown++;continue}soldCost+=it.costTotalC}for(const ret of selectedRet){const it=itemMap.get(ret.itemId);if(it&&!it.costMissing&&it.costTotalC!=null&&it.qtyBase>0)returnCost+=Math.round(it.costTotalC*ret.qtyBase/it.qtyBase)}return{selectedInv,items:selectedIt,returns:selectedRet,netSalesC:invoiced-refunded,netCostC:soldCost-returnCost,profitC:invoiced-refunded-soldCost+returnCost,unknown}}
renderInvoices=async function(){const filter=$('#invoiceFilter').value,r=await salesStats(filter),list=r.selectedInv.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));$('#invoiceStats').innerHTML=`<div class="stat"><small>صافي المبيعات بعد المرتجعات</small><b>${money(r.netSalesC)}</b></div><div class="stat"><small>المكسب النظري</small><b class="positive">${money(r.profitC)}</b>${r.unknown?`<div class="summary-warn">⚠ ${r.unknown} سطر مبيع بدون تكلفة شراء؛ تم احتساب تكلفته صفر مؤقتًا</div>`:''}</div><div class="stat"><small>عدد الفواتير</small><b>${list.length}</b></div><div class="stat"><small>مرتجعات الفترة</small><b>${money(r.returns.reduce((s,x)=>s+x.amountC,0))}</b></div>`;
 $('#invoiceList').innerHTML=list.length?list.map(i=>`<div class="list-card tap" data-invoice="${esc(i.id)}"><div class="card-top"><strong>${esc(i.number)}</strong><b>${money(i.totalC)}</b></div><div class="card-meta">${dateShow(i.createdAt)} · كاش ${money(i.cashC)}${i.creditC?' · آجل '+money(i.creditC):''} ${i.customerName?' · '+esc(i.customerName):''}${i.discountC?' · خصم '+money(i.discountC):''}${i.returnC?' · مرتجع '+money(i.returnC):''}</div></div>`).join(''):'<div class="blank">لا توجد فواتير</div>';$$('[data-invoice]').forEach(b=>b.onclick=()=>invoiceDetails(b.dataset.invoice))};
$('#invoiceFilter').insertAdjacentHTML('beforeend','<option value="week">آخر 7 أيام</option><option value="month">الشهر الحالي</option>');
invoiceDetails=async function(id){await originalInvoiceDetails(id);const inv=await one('invoices',id);if(!inv)return;const body=$('#sheetBody');body.insertAdjacentHTML('beforeend',`<div class="list-card spaced"><div class="split"><span>إجمالي الأصناف قبل الخصم</span><b>${money(inv.grossC??inv.totalC)}</b></div><div class="split"><span>خصم إجمالي الفاتورة</span><b>${money(inv.discountC||0)}</b></div><div class="hint">${inv.discountReason?'سبب الخصم: '+esc(inv.discountReason):''}</div></div><button id="printInvoice80" class="btn primary block spaced">🖨 معاينة وطباعة الفاتورة (80mm)</button>`);$('#printInvoice80').onclick=()=>printInvoice(inv.id)};
function receiptMarkup(invoice,items,mm){const unit=x=>displayQty({kind:x.kind,unit:x.unit},x.qtyBase);return `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>فاتورة ${esc(invoice.number)}</title><style>@page{size:${mm}mm auto;margin:3mm}*{box-sizing:border-box}body{font-family:Tahoma,Arial,sans-serif;font-size:11px;margin:0;padding:7px;color:#111;background:white}h2{text-align:center;font-size:17px;margin:3px 0}p{text-align:center;margin:4px 0}.split{display:flex;justify-content:space-between;border-bottom:1px dotted #bbb;padding:4px 0}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{text-align:right;padding:5px 0;border-bottom:1px dotted #bbb;word-break:break-word;font-size:10px}th:first-child,td:first-child{width:43%}strong{font-size:14px}.no-print{background:#eef5ee;padding:12px;border-radius:8px;margin-bottom:12px;text-align:center}.no-print button{padding:10px 15px;background:#116a35;color:white;border:0;border-radius:7px;font-size:14px}@media print{.no-print{display:none}}</style></head><body><div class="no-print">معاينة الفاتورة مقاس ${mm}mm — اختر الطابعة من نافذة الطباعة<br><button onclick="window.print()">طباعة الآن</button></div><h2>سدرة</h2><p>فاتورة بيع</p><p>${esc(invoice.number)}</p><p>${esc(dateShow(invoice.createdAt))}</p><table><thead><tr><th>الصنف</th><th>الكمية</th><th>الإجمالي</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.productName)}</td><td>${esc(unit(x))}</td><td>${money(x.grossC??x.totalC)}</td></tr>`).join('')}</tbody></table><div class="split"><span>قبل خصم الفاتورة</span><b>${money(invoice.grossC??invoice.totalC)}</b></div><div class="split"><span>خصم الفاتورة</span><b>${money(invoice.discountC||0)}</b></div><div class="split"><strong>الإجمالي</strong><strong>${money(invoice.totalC)}</strong></div><div class="split"><span>مدفوع عند البيع</span><b>${money(invoice.cashC)}</b></div><div class="split"><span>متبقي آجل</span><b>${money(invoice.creditC)}</b></div><p>شكرًا لزيارتكم</p></body></html>`}
async function printInvoice(id){const inv=await one('invoices',id);if(!inv)return;const items=(await all('items')).filter(x=>x.invoiceId===id);const size=await setting('printSize','80');const w=window.open('','_blank');if(!w)return toast('اسمح بفتح نافذة المعاينة من المتصفح');w.document.write(receiptMarkup(inv,items,size));w.document.close()}

/* Stock values and cash expected are independent financial metrics. */
async function currentFinance(){const [ps,cash,payables,ledger,purchases]=await Promise.all(['products','cash','payables','ledger','purchases'].map(all));let stockCostC=0,stockSaleC=0,unknown=0,stockNegative=0;for(const p of ps){if(!p.active)continue;const qty=Math.max(0,Number(p.stockQty)||0);stockSaleC+=isWeight(p)?Math.round(qty*p.priceC/1000):Math.round(qty*p.priceC);const cost=priceForBase(p);if(qty>0&&cost===null)unknown++;if(cost!==null)stockCostC+=Math.round(qty*cost);if(p.stockQty<0)stockNegative++}
 const opening=await setting('openingCashC',650000),movement=cash.reduce((s,x)=>s+x.amountC,0),supplierDebt=payables.reduce((s,x)=>s+x.amountC,0),customerDebt=ledger.reduce((s,x)=>s+x.amountC,0),expenses=cash.filter(x=>x.type==='expense'),paidToSupplier=cash.filter(x=>['purchase_payment','supplier_settlement','supplier'].includes(x.type)).reduce((s,x)=>s-x.amountC,0);return{stockCostC,stockSaleC,unknown,stockNegative,opening,movement,cashExpectedC:opening+movement,supplierDebt,customerDebt,expenses,paidToSupplier,purchases}}
async function updateBackupReminder(){if(!db)return;const last=await setting('lastBackupAt'),today=day(),overdue=!last||day(new Date(last))!==today,el=$('#backupDailyBanner'),hasProducts=(await all('products')).length>0;if(el){el.style.display=overdue&&hasProducts?'block':'none';if(overdue&&hasProducts)el.innerHTML=`⚠ <b>تذكير النسخ الاحتياطي اليومي</b> — ما نزلتش نسخة Backup اليوم. <button id="quickBackup" class="btn small outline" style="margin-right:6px">تنزيل الآن</button>`;$('#quickBackup')?.addEventListener('click',async()=>{await backup();toast('تم طلب تنزيل النسخة؛ احتفظ بها خارج الموبايل');await updateBackupReminder();renderMore()})}const hint=$('#backupReminder');if(hint)hint.textContent=last?'آخر طلب تنزيل Backup: '+dateShow(last)+(overdue?' · ⚠ لم يتم تنزيل نسخة اليوم':' · نسخة اليوم تم طلب تنزيلها'):'⚠ لم يتم طلب تنزيل نسخة احتياطية بعد'}
async function summaryRender(){if(!db)return;const s=await currentFinance(),target=$('#businessSummary');if(!target)return;target.innerHTML=`<div class="stat dashboard-tile"><small>قيمة البضاعة بسعر الشراء المسجل</small><b>${money(s.stockCostC)}</b></div><div class="stat dashboard-tile"><small>قيمة البضاعة بسعر البيع</small><b>${money(s.stockSaleC)}</b></div><div class="stat dashboard-tile"><small>المفروض كاش في الخزنة</small><b>${money(s.cashExpectedC)}</b></div><div class="stat dashboard-tile"><small>مديونيات الموردين</small><b class="amber">${money(s.supplierDebt)}</b></div><div class="stat dashboard-tile"><small>مديونيات العملاء</small><b>${money(s.customerDebt)}</b></div><div class="stat dashboard-tile"><small>المدفوع للموردين منذ البداية</small><b>${money(s.paidToSupplier)}</b></div>`;
 $('#businessSummaryWarnings').innerHTML=`<span class="notice-small">رصيد بداية الكاش: ${money(s.opening)} · صافي الحركات النقدية المسجلة: ${money(s.movement)}.</span>${s.unknown?`<div class="summary-warn">⚠ ${s.unknown} صنف موجود برصيد موجب بدون سعر شراء؛ قيمة المخزون بسعر التكلفة غير مكتملة، واعتُبرت تكلفتها صفرًا مؤقتًا.</div>`:''}${s.stockNegative?`<div class="summary-warn">⚠ ${s.stockNegative} صنف مخزونه بالسالب. الأرصدة السالبة مستبعدة من تقييم البضاعة ومطلوبة للمراجعة.</div>`:''}<div class="hint">المخزون أصل تجاري وليس كاشًا. الكاش يتأثر فقط بالمقبوضات والمدفوعات المسجلة، ولا يشمل ديون العملاء أو الموردين حتى تحصيلها/سدادها.</div>`;
 const sup=await supplierBalances();$('#supplierAccounts').innerHTML=sup.length?sup.slice(0,12).map(x=>`<div class="list-card split"><span>${esc(x.supplier)}</span><b class="amber">${money(x.amountC)}</b></div>`).join(''):'<div class="hint">لا توجد مديونيات موردين مسجلة.</div>';
 $('#recentPurchases').innerHTML=s.purchases.length?`<h3 style="margin:15px 0 8px;font-size:13px">آخر فواتير الوارد</h3>`+s.purchases.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,7).map(x=>`<div class="list-card"><div class="card-top"><b>${esc(x.number)}</b><b>${money(x.totalC)}</b></div><div class="card-meta">${esc(x.supplier||'مورد غير محدد')} · ${esc(x.rows?.length||0)} صف · مدفوع ${money(x.paidC)} · آجل عند التسجيل ${money(x.dueC)}</div></div>`).join(''):'';
 $('#expenseLog').innerHTML=s.expenses.length?`<p class="hint">مصروفات مسجلة من بداية التشغيل: ${money(-s.expenses.reduce((n,x)=>n+x.amountC,0))}</p>`+s.expenses.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,5).map(x=>`<div class="list-card split"><span>${esc(x.reference)}</span><b>${money(-x.amountC)}</b></div>`).join(''):'<div class="hint">لم تسجل مصروفات بعد.</div>'}
renderMore=async function(){await originalRenderMore();await Promise.all([summaryRender(),updateBackupReminder()])};
/* Use the requested starting cash only on a new database, not overwrite previous real movements. */
async function ensureCashOpening(){const initial=await setting('openingCashC');if(initial!==null)return;const cash=await all('cash');if(!cash.length){await saveSetting('openingCashC',650000);await saveSetting('openingCashDate',now())}else{await saveSetting('openingCashC',0);await saveSetting('openingCashNeedsReview',true);toast('توجد حركات قديمة؛ راجع بداية الكاش من الإدارة قبل اعتماد التقرير')}}
const oldCashClose=$('#closeDay').onclick;
$('#closeDay').onclick=async()=>{await oldCashClose();const open=$('#openCash');if(open&&open.value===''){const s=await currentFinance(),nowDay=day(),events=await all('cash'),before=events.filter(e=>e.dateKey<nowDay).reduce((sum,e)=>sum+e.amountC,0);open.value=moneyRaw(s.opening+before);open.dispatchEvent(new Event('input'))}};
window.sedraUpgradeInit=async function(){await ensureCashOpening();await updateBackupReminder();await summaryRender();setInterval(()=>{updateBackupReminder().catch(console.warn)},60_000)};
window.addEventListener('focus',()=>{if(db)updateBackupReminder().catch(console.warn)});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&db)updateBackupReminder().catch(console.warn)});
const originalBackupClick=$('#backup').onclick;
$('#backup').onclick=async()=>{await originalBackupClick();await updateBackupReminder()};
$('#receiptSize').onchange=async e=>{await saveSetting('printSize',e.target.value);toast('تم حفظ مقاس الطباعة')};
$('#reconcileCash').onclick=async()=>{if(!await ensureAdmin())return;const f=await currentFinance();modal('تسوية الكاش الفعلي',`<div class="stat"><small>المفروض كاش قبل التسوية</small><b>${money(f.cashExpectedC)}</b></div>${field('cashActuallyCounted','المبلغ المعدود فعليًا في الدرج (ج)','','number',moneyRaw(f.cashExpectedC))}${field('cashReconcileReason','السبب — إجباري','','text','تصحيح الكاش بعد العد')}<button class="btn primary block" id="applyReconcile">تأكيد تسوية الفرق فقط</button><p class="hint">التسوية تسجل حركة فرق مستقلة ولا تستبدل فواتير أو وارد أو مصروفات.</p>`);$('#applyReconcile').onclick=async()=>{const n=num($('#cashActuallyCounted').value),reason=$('#cashReconcileReason').value.trim();if(!(n>=0)||!Number.isFinite(n)||!reason)return toast('راجع المبلغ والسبب');const difference=cents(n)-f.cashExpectedC;if(!difference)return toast('الكاش مطابق ولا يحتاج تسوية');if(!confirm(`الفرق ${money(difference)}. تسجيل تسوية موثقة للسبب: «${reason}»؟`))return;const at=now(),tx=db.transaction(['cash','audit'],'readwrite');tx.objectStore('cash').add({id:uid('CA'),type:'cash_reconcile',amountC:difference,reference:reason,dateKey:day(),createdAt:at});tx.objectStore('audit').add({id:uid('AU'),action:'cash_reconcile',reference:reason,amountC:difference,actor:'admin',createdAt:at});await done(tx);closeModal();toast('تم تسجيل التسوية');renderMore()}};
const previousRenderMore=renderMore;
renderMore=async function(){await previousRenderMore();$('#receiptSize').value=await setting('printSize','80');const s=await currentFinance();if((await setting('openingCashNeedsReview',false))){$('#businessSummaryWarnings').insertAdjacentHTML('afterbegin','<div class="summary-warn">⚠ التطبيق وجد حركات كاش أقدم من التحديث؛ راجع الرصيد الفعلي وسوّه من الإدارة قبل اعتماد الإجمالي.</div>')}};
const previousExportDaily=exportDaily;
exportDaily=async function(dk,closing=null){const d=await daily(dk),s=daySummary(d),stat=await salesStats('all'),[allPurchases,allPayables,allStock,products]=await Promise.all(['purchases','payables','stock','products'].map(all)),purchases=allPurchases.filter(x=>x.dateKey===dk),payables=allPayables.filter(x=>x.dateKey===dk),name=new Map(products.map(p=>[p.id,p.name])),receipts=(await all('items')).filter(x=>x.dateKey===dk),returned=(await all('returns')).filter(x=>x.dateKey===dk),costKnown=receipts.reduce((sum,it)=>sum+(it.costTotalC||0),0),unknown=receipts.filter(x=>x.costMissing).length,retCost=returned.reduce((sum,r)=>{const it=allSaleItems.find(x=>x.id===r.itemId);return sum+(it&&!it.costMissing&&it.qtyBase>0?Math.round(it.costTotalC*r.qtyBase/it.qtyBase):0)},0);
 const periodProfit=s.invTotal-s.returns-costKnown+retCost;const finance=await currentFinance();const main=[['كاشير سدرة V5 - تقرير يومية',dk],['حالة اليوم',closing?'مغلق':'مؤقت'],['مبيعات الفواتير',moneyRaw(s.invTotal)],['مرتجعات اليوم',moneyRaw(s.returns)],['صافي مبيعات بعد المرتجعات',moneyRaw(s.invTotal-s.returns)],['المكسب النظري (تكلفة ناقصة=0)',moneyRaw(periodProfit)],['سطور بدون تكلفة شراء',unknown],['حركة الكاش اليوم',moneyRaw(s.netCash)],['رصيد افتتاحي للبرنامج',moneyRaw(finance.opening)],['الكاش الدفتري المتوقع حاليًا',moneyRaw(finance.cashExpectedC)],['مديونيات الموردين الحالية',moneyRaw(finance.supplierDebt)],['قيمة البضاعة بسعر الشراء المتاح',moneyRaw(finance.stockCostC)],['قيمة البضاعة بسعر البيع',moneyRaw(finance.stockSaleC)],['أصناف بدون تكلفة شراء',finance.unknown],['كاش فعلي عند إغلاق اليومية',closing?moneyRaw(closing.actualC):'غير مدخل']];
 const inv=[['رقم الفاتورة','التاريخ','المطلوب بعد الخصم','الإجمالي قبل الخصم','خصم الفاتورة','سبب الخصم','مدفوع كاش','آجل','مرتجع'],...d.invoices.map(x=>[x.number,x.createdAt,moneyRaw(x.totalC),moneyRaw(x.grossC??x.totalC),moneyRaw(x.discountC||0),x.discountReason||'',moneyRaw(x.cashC),moneyRaw(x.creditC),moneyRaw(x.returnC||0)])];
 const saleIt=[['رقم الفاتورة','الصنف','الكمية الأساسية','الوحدة','المبلغ بعد الخصم','تكلفة شراء محفوظة','تكلفة ناقصة','سبب تغيير السعر'],...receipts.map(x=>[x.number,x.productName,x.qtyBase,x.unit,moneyRaw(x.totalC),moneyRaw(x.costTotalC||0),x.costMissing?'نعم':'لا',x.priceReason||''])];
 const incoming=[['الفاتورة','التاريخ','المورد','الصنف','طريقة الإدخال','الكمية','الكمية الأساسية','سعر الوحدة','إجمالي السطر','إجمالي الفاتورة','مدفوع وقت الوارد','مديونية عند التسجيل'],...purchases.flatMap(p=>(p.rows||[]).map(r=>[p.number,p.createdAt,p.supplier,r.productName,r.unitName,r.qty,r.qtyBase,moneyRaw(r.unitCostC),moneyRaw(r.totalC),moneyRaw(p.totalC),moneyRaw(p.paidC),moneyRaw(p.dueC)]))];
 const supplier=[['التاريخ','المورد','نوع الحركة','المرجع','زيادة/نقص مديونية'],...payables.map(x=>[x.createdAt,x.supplier,x.type,x.reference,moneyRaw(x.amountC)])];
 const cash=[['التاريخ','نوع الحركة','البيان','داخل/خارج'],...d.cash.map(x=>[x.createdAt,x.type,x.reference,moneyRaw(x.amountC)])];
 const stock=[['التاريخ','الصنف','نوع الحركة','الكمية الأساسية (+/-)','المرجع'],...allStock.filter(x=>x.dateKey===dk).map(x=>[x.createdAt,name.get(x.productId)||x.productId,x.type,x.qtyBase,x.reference])];
 const led=[['التاريخ','العميل','نوع الحركة','تغير المديونية'],...d.ledger.map(x=>[x.createdAt,x.customerId,x.type,moneyRaw(x.amountC)])];
 const old=[['التاريخ','القيمة','النوع','التفاصيل','الحالة'],...(await all('historical')).map(x=>[x.dateKey,moneyRaw(x.amountC),x.type,x.note,x.status||'active'])];
 downloadBlob(`Sedra_V5_Daily_${dk}.xlsx`,makeXlsx([{name:'الملخص',rows:main},{name:'فواتير البيع',rows:inv},{name:'أصناف مباعة',rows:saleIt},{name:'فواتير الوارد',rows:incoming},{name:'ديون الموردين',rows:supplier},{name:'الخزنة والمصروفات',rows:cash},{name:'حركة المخزون',rows:stock},{name:'مديونيات العملاء',rows:led},{name:'مبيعات قديمة',rows:old}]))};
